SELECT 'gongkao', '属性规律概述', 'kp-xc-tutui-prop-overview', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"属性规律概述"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"识别特征：","marks":[{"type":"bold"}]},{"type":"text","text":"元素组成不同但图形规整、有明显的对称/曲直/封闭特征。约占图形推理的 10%。属性规律关注的是图形的「性质」而非「数量」。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、包含的子类"}]},{"type":"columns","attrs":{"cols":2},"content":[{"type":"column","attrs":{"index":0},"content":[{"type":"paragraph","content":[{"type":"text","text":"子类","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"对称性：轴对称、中心对称"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"曲直性：全直、全曲、有曲有直"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"开闭性：全开放、全封闭、半开半闭"}]}]}]}]},{"type":"column","attrs":{"index":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"考频","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"对称性：约 280 题（高频）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"曲直性：约 50 题（低频）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"开闭性：约 50 题（低频）"}]}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心判断逻辑"}]},{"type":"textDiagram","attrs":{"language":"mermaid"},"content":[{"type":"text","text":"flowchart TD\n    A[元素不同但图形规整] --> B{有对称感?}\n    B -->|是| C[对称性]\n    B -->|否| D{全直/全曲?}\n    D -->|是| E[曲直性]\n    D -->|否| F{开放/封闭?}\n    F -->|是| G[开闭性]\n    F -->|否| H[考虑数量规律]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、与其他类别的区分"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"属性规律 vs 数量规律：属性是「看性质」，数量是「数个数」"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"属性和数量常复合出现，如「面数都是 4 + 都是有曲有直」"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"学习建议：","marks":[{"type":"bold"}]},{"type":"text","text":"对称性是属性类最高频考点，必须熟练掌握轴对称与中心对称的判断。曲直性和开闭性虽然考频低，但常作为辅助判断条件出现。"}]}]}]}$$ AS jsonb), NULL, '属性规律概述：对称性、曲直性、开闭性的识别特征、判断逻辑、考频分布。', category_node.id, CAST('["图形推理", "属性规律", "概述"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_logic_figure_reasoning_property", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
